// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // General idea: the correct contract requires msg.sender == owner. The mutant checks tx.origin == owner.
    // We fuzz an arbitrary EOA 'actor' and an arbitrary address 'newOwner'. We deploy a helper caller contract
    // that will call c.setOwner(newOwner). When the helper is the caller, msg.sender == helper, and tx.origin == actor.
    // The correct contract should only allow the change if helper == current owner (which it won't be), so setOwner should
    // revert / fail. The mutant that checks tx.origin == owner would allow the call if actor == owner. We choose actor
    // to be the original owner (the deployer of c in setUp()), and then the mutant would allow the helper to change owner,
    // while the correct contract forbids helper from changing owner. We assert the invariant that for all actor and newOwner,
    // after the helper attempts the call with origin actor, the owner remains unchanged when the caller is not the owner.

    // Fuzz parameters: actor (originating EOA) and newOwner (address to set).
    function testFuzz_property(address actor, address newOwner) public {
        // keep actor non-zero and not equal to address(this) to be a meaningful EOA
        vm.assume(actor != address(0));
        // ensure helper (a contract we deploy) is not the current owner
        HelperCaller helper = new HelperCaller(c);
        vm.assume(address(helper) != address(c));

        // The contract C was deployed in setUp() by this test contract, so c.owner() == address(this).
        // We want the tx.origin to be 'actor' (an EOA) so we must make 'actor' be the EOA that initiates the call.
        // Use vm.prank to set tx.origin and msg.sender for an EOA call; then inside the helper, it will perform a call to c
        // so msg.sender for C will be the helper contract, while tx.origin remains actor.

        // Give the actor some ETH so they can be used as tx.origin in a prank (not strictly necessary but safe)
        vm.deal(actor, 1 ether);

        // The deciding general rule we assert: if the immediate caller is not the current owner, the owner should remain unchanged after the call.
        // This holds for the reference contract for ALL inputs: only msg.sender==owner can change owner. The mutant that checks tx.origin
        // can be tricked when tx.origin==owner (i.e., actor == original owner) and a helper contract calls setOwner: mutant will change owner,
        // violating the rule for some inputs. Our single assertion checks c.owner() unchanged after the helper call when caller != owner.

        // Ensure helper is not the owner (owner is address(this))
        vm.assume(address(helper) != c.owner());

        // Have the EOA 'actor' call the helper which will call c.setOwner(newOwner)
        vm.prank(actor);
        helper.callSetOwner(newOwner);

        // Single assertion: owner must remain address(this) because msg.sender (the helper) was not the owner.
        assertTrue(c.owner() == address(this));
    }
}

// Helper contract that forwards a call to C; when invoked by an EOA (tx.origin = that EOA), this contract's call to C will have
// msg.sender = address(this) and tx.origin = the EOA. This exposes the difference between checking msg.sender vs tx.origin.
contract HelperCaller {
    C c;
    constructor(C _c) {
        c = _c;
    }
    function callSetOwner(address newOwner) external {
        // forward call; any revert will propagate
        c.setOwner(newOwner);
    }
}

