        // Make the current test caller the owner so onlyOwner passes.
        address caller = address(this);
        // deployer of C in setUp() is this contract, so this contract is owner already
        // call setOwner with fuzzed newOwner
        bool ok;
        try c.setOwner(newOwner) {
