pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: attacker (the reentrant helper) and the target newOwner address
    function testFuzz_property(address attackerAddr, address newOwner) public {
        // Keep admissible domain wide but avoid the zero address for clarity (still wide)
        // Allow fuzz to choose attackerAddr freely; if it's zero we deploy helper at a new address anyway.
        vm.assume(newOwner != address(0));

        // Deploy a reentrant helper that, when called (during assignment), will call back into c.setOwner(sabotageOwner)
        // We will set sabotageOwner to some different address (flip bit) to try to break mutant.
        ReentrantHelper helper = new ReentrantHelper(c);

        // Fund helper so it can make calls if needed
        vm.deal(address(helper), 1 ether);

        // Ensure c.owner() is the test's msg.sender by performing actions as the deployer of c (setUp used new C() from test contract)
        // In this test, the test contract is the deployer of c, so it's the owner already. Confirm that.
        address currentOwner = c.owner();
        assertTrue(currentOwner == address(this));

        // Choose a sabotage target different from newOwner to observe a difference if reentrancy occurs
        address sabotageOwner = address(uint160(uint256(keccak256(abi.encodePacked(newOwner, block.timestamp)))));
        if (sabotageOwner == newOwner) {
            // ensure different
            sabotageOwner = address(uint160(uint256(keccak256(abi.encodePacked(newOwner, block.number)))));
        }

        // Configure helper to reenter and set owner to sabotageOwner when its fallback is triggered
        helper.configureReentry(sabotageOwner);

        // Now perform the call as the owner (this contract) and pass helper's address as the newOwner parameter
        // The property: after setOwner(helperAddr) returns, c.owner() == helperAddr for the correct contract
        // For mutant with a second assignment, helper can reenter between assignments and change owner back to sabotageOwner,
        // causing c.owner() != helperAddr after completion.

        // Call
        bool ok;
        try c.setOwner(address(helper)) {
            ok = true;
        } catch {
            ok = false;
        }

        // Single assertion: the reference guarantees successful completion and final owner equals the supplied address (helper)
        // We assert that call succeeded and owner equals the supplied address. The mutant (with double assignment) can be broken by the helper's reentry.
        assertTrue(ok && c.owner() == address(helper));
    }
}

// Minimal reentrant helper: when its fallback is invoked it calls back into c.setOwner(sabotage) to overwrite owner
contract ReentrantHelper {
    C public target;
    address public sabotage;
    bool public configured;

    constructor(C _target) {
        target = _target;
        configured = false;
    }

    function configureReentry(address _sabotage) external {
        sabotage = _sabotage;
        configured = true;
    }

    // Any call to this contract's fallback will trigger reentry once
    fallback() external payable {
        if (configured) {
            // attempt to reenter into target.setOwner to change owner to sabotage
            // ignore failures
            try target.setOwner(sabotage) {} catch {}
        }
    }

    receive() external payable {
        if (configured) {
            try target.setOwner(sabotage) {} catch {}
        }
    }
}

