    // General rule: when the current owner calls setOwner(target), the call completes
    // and afterward c.owner() == target for all target addresses — the mutant with
    // two sequential assignments can be disrupted if a reentrant helper re-enters
    // between the two assignments and sets owner to something else. We deploy a
    // helper (ReentrantHelper) at the fuzzed address by funding/using that address
    // as the caller for the helper deployment and then have C interact with it.
    function testFuzz_property(address attackerAddr) public {
        // Keep domain wide but non-zero for attackerAddr to avoid 0x0 confusion
        // (still allow any address otherwise).
        vm.assume(attackerAddr != address(0));

        // Deploy a reentrant helper that, when it receives a call during owner assignment,
        // will call back into C and change owner to attackerAddr to try to exploit two writes.
        ReentrantHelper helper = new ReentrantHelper(c, attackerAddr);

        // Ensure the test actor is the initial owner (deployer in setUp()).
        address initialOwner = address(this);
        assertTrue(c.owner() == initialOwner);

        // Now the owner (this) will call setOwner with the helper's address as target.
        // The helper is crafted to, when it is used in an assignment (we simulate this by
        // having its fallback reenter), attempt to reenter and set owner to attackerAddr.
        bool ok;
        try c.setOwner(address(helper)) {
            ok = true;
        } catch {
            ok = false;
        }

        // Single assertion: for the correct contract C (reference), for any attackerAddr
        // and deployed helper, the call completes (ok == true) and after completion
        // c.owner() equals the supplied target (address(helper)). The mutant with two
        // consecutive assignments can be broken by the helper reentering between them,
        // causing c.owner() != address(helper) for some attackerAddr; thus this
        // assertion will fail on the mutant for some fuzz input.
        assertTrue(ok && c.owner() == address(helper));
    }
}

