// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzer supplies the newOwnerContract flag (0 or 1) and a random salt to vary addresses/contracts
    function testFuzz_property(uint256 salt, bool useReentrant) public {
        // keep domain wide; only constrain salt to something reasonable
        salt = bound(salt, 1, type(uint256).max);

        // deploy a reentrant helper when requested; otherwise use a plain EOA-like address
        address target;
        ReentrantAttacker attacker;
        if (useReentrant) {
            attacker = new ReentrantAttacker(c);
            target = address(attacker);
        } else {
            // derive a pseudo-random EOA-like address by deploying a dumb passthrough contract
            Passthrough p = new Passthrough();
            target = address(p);
        }

        // current owner is address(this) because setUp deployed c from this contract
        // call setOwner as the owner to set to target
        bool ok;
        try c.setOwner(target) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: for the correct reference, the call should succeed and owner() equals target
        // We assert that owner() == target when the call returned successfully.
        // This single assertion is satisfied by the reference for all inputs, but the mutant with
        // a second assignment can be broken by the reentrant attacker altering owner between assignments,
        // producing a case where ok==true but owner()!=target.
        if (ok) {
            assertTrue(c.owner() == target);
        } else {
            // if the call reverted, still assertTrue(false) would be invalid; keep property only when call succeeded
            // but to keep a single assertTrue per test requirement, we assert that false==false (no-op) by asserting owner==owner
            // However the specification requires exactly one assertTrue that reads c; in the revert case owner unchanged equals owner
            assertTrue(c.owner() == c.owner());
        }
    }
}

// Minimal reentrant attacker: during being set as owner, it will re-enter setOwner to change owner again
contract ReentrantAttacker {
    C c;
    bool reentered;
    constructor(C _c) { c = _c; }
    receive() external payable {}
    fallback() external {
        // try to re-enter only once to avoid infinite recursion
        if (!reentered) {
            reentered = true;
            // attempt to change owner back to address(this)
            // ignore failures
            try c.setOwner(address(this)) {} catch {}
        }
    }
}

// Simple passthrough contract to serve as a non-reentrant target
contract Passthrough {
    receive() external payable {}
}
